mapper.select:
SELECT p.id, p.project_code, p.name, p.status, p.priority, p.project_type, p.customer_id, c.name AS customer_name, c.contact_person, c.contact_phone, c.contact_email, p.manager_name, p.manager_phone, p.address, p.region, p.start_date, p.end_date, p.contract_amount, p.budget, p.progress, p.description, DATE_FORMAT(p.created_at, '%Y-%m-%d') AS created_at, DATE_FORMAT(p.updated_at, '%Y-%m-%d') AS updated_at, p.is_archived FROM biz_project p LEFT JOIN biz_customer c ON p.customer_id = c.id
AND p.is_archived = 1 0
AND (p.name LIKE CONCAT('%', #{query.keyword}, '%') OR p.project_code LIKE CONCAT('%', #{query.keyword}, '%'))
AND p.status = #{query.status}
AND p.project_type = #{query.type}
AND p.priority = #{query.priority}
AND p.manager_name LIKE CONCAT('%', #{query.manager}, '%')
AND p.start_date >= #{query.startDateBegin}
AND p.start_date <= #{query.startDateEnd}
AND 1 = 0
AND p.id IN
#{pid}
ORDER BY p.created_at DESC, p.id DESC

SELECT customer_id AS customerId, COUNT(*) AS cnt FROM biz_project WHERE customer_id IN
#{cid}
GROUP BY customer_id
